//! Black-box tests: run the built `monokl` binary against the `small-ts` fixture project.
#![allow(clippy::unwrap_used, clippy::expect_used, reason = "a failing assertion should panic in a test")]

use std::path::PathBuf;
use std::process::{Command, Output};

fn fixture() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/small-ts")
}

/// Runs `monokl` with the fixture as the working directory, so printed paths are relative.
fn monokl(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_monokl")).args(args).current_dir(fixture()).output().unwrap()
}

fn stdout(output: &Output) -> String {
    String::from_utf8(output.stdout.clone()).unwrap()
}

fn stderr(output: &Output) -> String {
    String::from_utf8(output.stderr.clone()).unwrap()
}

#[test]
fn search_prints_ranked_blocks_with_relative_paths() {
    let output = monokl(&["search", "format", "."]);
    assert!(output.status.success(), "stderr: {}", stderr(&output));
    let text = stdout(&output);
    let mut lines = text.lines();
    assert_eq!(lines.next(), Some("search[3]{file,lineStart,lineEnd,nodeKind,symbolSignature,rank,finalScore}:"));
    let first = lines.next().unwrap();
    assert!(
        first.starts_with(
            "  src/utils/format.ts,1,3,function,\"function formatCurrency(amount: number, currency: string = 'USD'): string\",1,"
        ),
        "got: {first}"
    );
    assert!(text.lines().all(|line| !line.contains("/Users/")), "paths should be relative: {text}");
}

#[test]
fn search_is_deterministic() {
    assert_eq!(stdout(&monokl(&["search", "price", "."])), stdout(&monokl(&["search", "price", "."])));
}

#[test]
fn search_honours_the_result_cap_and_says_so() {
    let output = monokl(&["search", "price", ".", "--max-results", "2"]);
    let text = stdout(&output);
    assert!(text.starts_with("search[2]"), "got: {text}");
    assert!(text.contains("totalCount: 8"), "got: {text}");
    assert!(text.contains("showing 2 of 8"), "got: {text}");
}

#[test]
fn excluded_terms_remove_files() {
    let with = stdout(&monokl(&["search", "price", "."]));
    let without = stdout(&monokl(&["search", "price -validation", "."]));
    assert!(with.contains("src/utils/validation.ts"));
    assert!(!without.contains("src/utils/validation.ts"));
}

#[test]
fn a_query_with_no_match_prints_an_empty_result() {
    let output = monokl(&["search", "zzzqqqxx", "."]);
    assert!(output.status.success());
    assert!(stdout(&output).starts_with("search: []"), "got: {}", stdout(&output));
}

#[test]
fn an_invalid_regex_fails_with_a_structured_error() {
    let output = monokl(&["search", "regex:(", "."]);
    assert_eq!(output.status.code(), Some(1));
    assert_eq!(stdout(&output), "");
    assert!(stderr(&output).starts_with("error: invalid_input"), "got: {}", stderr(&output));
    assert!(stderr(&output).contains("regex_build"), "got: {}", stderr(&output));
}

#[test]
fn a_missing_query_is_a_usage_error() {
    let output = monokl(&["search"]);
    assert_eq!(output.status.code(), Some(2));
    assert!(stderr(&output).contains("<QUERY>"));
}
        Err(text) => {
            let _written = writeln!(err, "{text}");
            ExitCode::FAILURE
        }
    }
}

fn registry() -> AnalyzerRegistry {
    #[cfg(feature = "lang-ts")]
    let analyzers: Vec<Arc<dyn crate::analysis::LanguageAnalyzer>> =
        vec![Arc::new(crate::analysis::ts::TsAnalyzer::new())];
    #[cfg(not(feature = "lang-ts"))]
    let analyzers: Vec<Arc<dyn crate::analysis::LanguageAnalyzer>> = Vec::new();
    AnalyzerRegistry::new(analyzers)
}

fn run_search(args: &SearchArgs) -> Result<String, String> {
    let request = SearchRequest {
        root: &args.path,
        query: &args.query,
        exact: args.exact,
        allow_tests: args.tests,
        respect_ignore_files: !args.no_ignore,
        language: args.language,
    };
    let result = search(&registry(), &request).map_err(|e| error_text(&e))?;

    let mut ranked = result.ranked;
    let mut diagnostics = result.diagnostics;
    // Paths print relative to the working directory when they are under it, so every row spends fewer tokens.
    if let Some(cwd) = std::env::current_dir().ok().and_then(|dir| Utf8PathBuf::from_path_buf(dir).ok()) {
        for block in &mut ranked {
            relativize(&mut block.block.file, &cwd);
        }
        for diagnostic in &mut diagnostics {
            if let Some(path) = &mut diagnostic.path {
                relativize(path, &cwd);
            }
        }
    }
    if result.ceiling_hit {
        diagnostics.push(Diagnostic {
            kind: DiagnosticKind::Warning,
            path: None,
            message: format!(
                "{} files matched but hits were kept for only the first {DEFAULT_MAX_FILES}; narrow the query or path",
                result.files_total
            ),
        });
    }
    let budget = Budget { max_results: args.max_results, max_tokens: args.max_tokens, max_bytes: args.max_bytes };
    let total_before = ranked.len();
    let response = apply_budget(ranked, total_before, &budget, diagnostics);
    render_projection(&response).map_err(|e| e.render())
}

fn relativize(path: &mut Utf8PathBuf, base: &Utf8PathBuf) {
    if let Ok(relative) = path.strip_prefix(base) {
        *path = relative.to_owned();
    }
}

fn error_text(error: &MonoklError) -> String {
    error.to_domain_error(ErrorContext { command: "search" }).render()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run_args(args: &[&str]) -> (ExitCode, String, String) {
        let (mut out, mut err) = (Vec::new(), Vec::new());
        let code = run(std::iter::once("monokl").chain(args.iter().copied()), &mut out, &mut err);
        (code, String::from_utf8(out).unwrap(), String::from_utf8(err).unwrap())
    }

    #[test]
    fn help_goes_to_stdout_and_succeeds() {
        let (code, out, err) = run_args(&["--help"]);
        assert_eq!(code, ExitCode::SUCCESS);
        assert!(out.contains("Searches a directory"), "got: {out}");
        assert_eq!(err, "");
    }

    #[test]
    fn a_missing_query_is_a_usage_error_on_stderr() {
        let (code, out, err) = run_args(&["search"]);
        assert_eq!(code, ExitCode::from(2));
        assert_eq!(out, "");
        assert!(err.contains("<QUERY>"), "got: {err}");
    }

    #[test]
    fn a_missing_directory_is_a_structured_error_on_stderr() {
        let (code, out, err) = run_args(&["search", "alpha", "/definitely/not/a/directory"]);
        assert_eq!(code, ExitCode::FAILURE);
        assert_eq!(out, "");
        assert!(err.starts_with("error: not_found"), "got: {err}");
    }
}

