            ("sub/b.ts", "alpha\nbeta\n"),
            ("sub/deep/c.ts", "alpha alpha\n"),
            ("d.ts", "beta alpha gamma\n"),
        ]);
        let run = || {
            let result = search(&whole_file_registry(), &request(&root, "alpha beta -zzz")).unwrap();
